#include "resident/kernel/catalog_section_observation.hpp"
// 原亲缘图严格有限且无环；全局真值只供权威准入，不自动授予人物知情。
#include "family_lineage.hpp"
#include <algorithm>
#include <map>
#include <set>
namespace hanmo::resident {namespace {
// 初始人物资格同时要求目录和共同身份；新造的同名字段不能冒充原人物。
bool authored(const CommonStore& c,const CommonCatalog& catalog,const StableId& actor){return !actor.empty()&&actor.size()<=256&&c.actor(actor)&&std::find(catalog.actor_ids.begin(),catalog.actor_ids.end(),actor)!=catalog.actor_ids.end();}
// 图已核无环后才求祖先；未知亲代在此停止，不补“无亲缘”结论。
std::set<StableId> ancestors(const FamilyLineageCatalog& catalog,const StableId& actor){std::set<StableId> result;std::vector<StableId> pending{actor};while(!pending.empty()){auto id=std::move(pending.back());pending.pop_back();if(const auto* origin=catalog.origins.find(id))for(const auto& parent:origin->parent_actor_ids)if(result.insert(parent).second)pending.push_back(parent);}return result;}
}
Status validate_family_lineage_catalog(const CommonStore& c,const CommonCatalog& common,const FamilyLineageCatalog& catalog){
  // 只旁观本次原入口；返回值与首错仍由原函数独占。
  ::hanmo::resident::catalog_section_observation::Scope catalog_cost_observation(
      ::hanmo::resident::catalog_section_observation::Kind::catalog_validation, 34, "FamilyLineageCatalog", "validate_family_lineage_catalog", &catalog);

    if(!catalog.enabled)return catalog.origins.empty()&&catalog.original_innate_levels.empty()&&catalog.endowment.families.empty()?common_success():common_failure("FamilyLineageProfileRequired");
    if(catalog.origins.size()>4096||catalog.original_innate_levels.size()>4096)return common_failure("FamilyLineageCatalogLimit");auto valid=validate_birth_endowment_policy(catalog.endowment,common.extended_skills);if(!valid.ok)return valid;
    for(const auto& row:catalog.origins.rows()){const auto& origin=row.second;if(row.first!=origin.actor_id||!authored(c,common,origin.actor_id)||origin.parent_actor_ids.size()>2||std::set<StableId>(origin.parent_actor_ids.begin(),origin.parent_actor_ids.end()).size()!=origin.parent_actor_ids.size())return common_failure("InvalidBiologicalOrigin",row.first);for(const auto& parent:origin.parent_actor_ids){if(parent==origin.actor_id||!authored(c,common,parent))return common_failure("InvalidBiologicalParent",row.first);const auto* older=c.state().actors.find(parent);const auto* younger=c.state().actors.find(origin.actor_id);if(older->birth_tick&&younger->birth_tick&&*older->birth_tick>=*younger->birth_tick)return common_failure("BiologicalParentBirthOrder",row.first);}}
    // 使用显式栈防恶意长家系耗尽调用栈；灰色节点只表示当前祖先路径。
    std::map<StableId,Integer> colors;for(const auto& row:catalog.origins.rows()){if(colors[row.first]==2)continue;std::vector<std::pair<StableId,std::size_t>> stack{{row.first,0}};colors[row.first]=1;while(!stack.empty()){auto& top=stack.back();const auto* origin=catalog.origins.find(top.first);if(!origin||top.second==origin->parent_actor_ids.size()){colors[top.first]=2;stack.pop_back();continue;}const auto parent=origin->parent_actor_ids[top.second++];if(colors[parent]==1)return common_failure("BiologicalParentCycle",parent);if(colors[parent]==0){colors[parent]=1;stack.emplace_back(parent,0);}}}
    for(const auto& row:catalog.original_innate_levels.rows()){if(!authored(c,common,row.first)||row.second.size()>catalog.endowment.families.size())return common_failure("InvalidOriginalInnateActor",row.first);for(const auto& level:row.second.rows())if(!catalog.endowment.families.find(level.first)||level.second<0||level.second>3)return common_failure("InvalidOriginalInnateLevel",row.first);}return common_success();
}
Outcome<BiologicalRelationRead> read_original_biological_relation(const CommonStore& c,const CommonCatalog& common,const FamilyLineageCatalog& catalog,const StableId& first,const StableId& second){auto valid=validate_family_lineage_catalog(c,common,catalog);if(!valid.ok)return {false,{},valid.error};if(!catalog.enabled||!authored(c,common,first)||!authored(c,common,second)||first==second)return {false,{},common_failure("BiologicalRelationUnavailable").error};BiologicalRelationRead out;out.source_identity=c.state().identity;out.first_actor_id=first;out.second_actor_id=second;const auto a=ancestors(catalog,first),b=ancestors(catalog,second);out.known_direct_line=a.count(second)||b.count(first);const auto* x=catalog.origins.find(first);const auto* y=catalog.origins.find(second);out.first_parents_complete=x&&x->parent_actor_ids.size()==2;out.second_parents_complete=y&&y->parent_actor_ids.size()==2;if(x&&y)for(const auto& parent:x->parent_actor_ids)if(std::find(y->parent_actor_ids.begin(),y->parent_actor_ids.end(),parent)!=y->parent_actor_ids.end())out.common_parent_actor_ids.push_back(parent);out.known_siblings=!out.common_parent_actor_ids.empty();return {true,std::move(out),{}};}
Outcome<InnateParentSource> read_original_innate_parent(const CommonStore& c,const CommonCatalog& common,const FamilyLineageCatalog& catalog,const std::optional<StableId>& actor,const StableId& family){auto valid=validate_family_lineage_catalog(c,common,catalog);if(!valid.ok)return {false,{},valid.error};if(!catalog.enabled||!catalog.endowment.families.find(family))return {false,{},common_failure("UnknownInnateFamily",family).error};if(!actor)return {true,{}, {}};if(!authored(c,common,*actor))return {false,{},common_failure("OriginalInnateSourceUnavailable",*actor).error};InnateParentSource out;out.actor_id=actor;if(const auto* levels=catalog.original_innate_levels.find(*actor))if(const auto* level=levels->find(family))out.level=*level;return {true,std::move(out),{}};}
}
